 3	namespace testsuites\Application\Admin\Wizard;
 4	
 5	use Application_Countries;
 6	use Application_Driver;
 7	use AppLocalize\Localization\Country\CountryGB;
 8	use AppFrameworkTestClasses\ApplicationTestCase;
 9	use TestDriver_Area_WizardTest_Wizard;
10	
11	final class WizardTest extends ApplicationTestCase
12	{
13	    protected TestDriver_Area_WizardTest_Wizard $wizard;
14	
15	    public function setUp() : void
16	    {
17	        parent::setUp();
18	        $this->startTransaction();
19	
20	        $this->cleanUpTables(array(Application_Countries::TABLE_NAME));
21	
22	        $driver = Application_Driver::getInstance();
23	        $screen = $driver->getScreenByPath('wizardtest.wizard');
24	
25	        $this->assertNotNull($screen, 'Screen could not be found by path.');
26	        $this->assertInstanceOf(TestDriver_Area_WizardTest_Wizard::class, $screen);
27	
28	        $this->wizard = $screen;
29	    }
30	
31	    public function test_wizardSteps() : void
32	    {
33	        $this->wizard->handleActions();
34	        $countriesStep = $this->wizard->getStep('Countries');
35	
36	        $ticketStep = $this->wizard->getStep('Ticket');
37	        $ticketStep->process();
38	        $this->assertTrue($ticketStep->isComplete());
39	
40	        $summaryStep = $this->wizard->getStep('Summary');
41	        $summaryStep->process();
42	        $this->assertTrue($summaryStep->isComplete());
43	
44	        $this->wizard->changeCountry(CountryGB::ISO_CODE);
45	        $countriesStep->process();
46	        $this->assertFalse($ticketStep->isComplete());
47	        $this->assertFalse($summaryStep->isComplete());
48	    }
49	}

