  9	use Application\Admin\Wizard\WizardConfigurator;
 10	use Application\AppFactory;
 11	
 12	/**
 13	 * Test-application mode screen that demonstrates the {@see WizardConfigurator}
 14	 * preselection API.
 15	 *
 16	 * Navigating to `?page=wizardtest&mode=preselection&country=GB` creates a wizard
 17	 * session with the `country_id` field on the Countries step pre-populated with the
 18	 * ID that corresponds to the given ISO code, then immediately redirects the browser
 19	 * to the wizard at that session.
 20	 *
 21	 * When no valid `?country=` parameter is present, the screen renders a short usage
 22	 * note so the user knows how to exercise it manually — making it a self-contained
 23	 * UI test for the preselection feature.
 24	 *
 25	 * The class is auto-discovered by {@see Application_Admin_Index_AdminScreenIndex}
 26	 * via the PSR-0 filesystem / classmap convention: placing the file under
 27	 * `TestDriver/Area/WizardTest/` is sufficient; no explicit registration in
 28	 * {@see TestDriver_Area_WizardTest} is required.
 29	 *
 30	 * @package TestDriver
 31	 * @subpackage WizardTest
 32	 * @see WizardConfigurator
 33	 */
 34	class TestDriver_Area_WizardTest_Preselection extends Application_Admin_Area_Mode
 35	{
 36	    public const string URL_NAME = 'preselection';
 37	
 38	    public const string REQUEST_PARAM_COUNTRY = 'country';
 39	
 40	    public function getURLName() : string
 41	    {
 42	        return self::URL_NAME;
 43	    }
 44	
 45	    public function getDefaultSubmode() : string
 46	    {
 47	        return '';
 48	    }
 49	
 50	    public function isUserAllowed() : bool
 51	    {
 52	        return true;
 53	    }
 54	
 55	    public function getNavigationTitle() : string
 56	    {
 57	        return t('Preselection Test');
 58	    }
 59	
 60	    public function getTitle() : string
 61	    {
 62	        return t('Wizard Preselection Test');
 63	    }
 64	
 65	    /**
 66	     * Handles the request: if a valid `?country=<ISO>` parameter is present,
 67	     * builds a WizardConfigurator preselection session and redirects to the
 68	     * wizard.  Otherwise falls through to {@see _renderContent()} for manual
 69	     * usage instructions.
 70	     *
 71	     * @return bool
 72	     */
 73	    protected function _handleActions() : bool
 74	    {
 75	        $iso = (string)$this->request->getParam(self::REQUEST_PARAM_COUNTRY, '');
 76	
 77	        if(empty($iso)) {
 78	            return true;
 79	        }
 80	
 81	        $countries = AppFactory::createCountries();
 82	
 83	        if(!$countries->isoExists($iso)) {
 84	            return true;
 85	        }
 86	
 87	        $country = $countries->getByISO($iso);
 88	
 89	        $wizardBaseURL = $this->area->getURL(array(
 90	            'mode' => TestDriver_Area_WizardTest_Wizard::URL_NAME
 91	        ));
 92	
 93	        $configurator = new WizardConfigurator($wizardBaseURL);
 94	        $configurator->getPreselection()->setStepValue(
 95	            'Countries',
 96	            TestDriver_Area_WizardTest_Wizard_Step_Countries::VALUE_COUNTRY_ID,
 97	            $country->getID()
 98	        );
 99	
100	        $this->redirectTo($configurator->getRedirectURL());

